-- Gizlemenin RLS politikasini gercekten kestigini olcuyoruz. Politika
-- auth.uid() kullandigi icin rol ve talep taklit ediliyor.
do $$
declare
  v_kullanici uuid;
  v_checkin   uuid;
  v_gorunen   int;
begin
  select kullanici_id into v_kullanici from public.check_inler limit 1;
  if v_kullanici is null then
    raise notice 'ATLANDI: hic check-in yok';
    return;
  end if;
  select id into v_checkin from public.check_inler where kullanici_id = v_kullanici limit 1;

  update public.check_inler set moderasyon_gizli = true where id = v_checkin;

  -- Sahibinin kimligiyle bak: karar 60 geregi sahibi de gormemeli.
  perform set_config('request.jwt.claims',
    json_build_object('sub', v_kullanici, 'role', 'authenticated', 'aal', 'aal1')::text, true);
  perform set_config('role', 'authenticated', true);

  select count(*) into v_gorunen from public.check_inler where id = v_checkin;
  raise notice 'gizliyken sahibine gorunen satir: %', v_gorunen;

  perform set_config('role', 'postgres', true);
  update public.check_inler set moderasyon_gizli = false where id = v_checkin;

  perform set_config('request.jwt.claims',
    json_build_object('sub', v_kullanici, 'role', 'authenticated', 'aal', 'aal1')::text, true);
  perform set_config('role', 'authenticated', true);
  select count(*) into v_gorunen from public.check_inler where id = v_checkin;
  raise notice 'gizleme kalkinca sahibine gorunen satir: %', v_gorunen;

  perform set_config('role', 'postgres', true);
end $$;

create or replace function pg_temp.gizleme_olc()
returns table(asama text, gorunen int)
language plpgsql
as $fn$
declare
  v_kullanici uuid;
  v_checkin   uuid;
  v_sayi      int;
begin
  select c.kullanici_id, c.id into v_kullanici, v_checkin
    from public.check_inler c limit 1;
  if v_checkin is null then
    asama := 'ATLANDI - hic check-in yok'; gorunen := -1; return next; return;
  end if;

  -- Sahibinin kimligini taklit et.
  perform set_config('request.jwt.claims',
    json_build_object('sub', v_kullanici, 'role', 'authenticated', 'aal', 'aal1')::text, true);

  update public.check_inler set moderasyon_gizli = true where id = v_checkin;
  set local role authenticated;
  select count(*) into v_sayi from public.check_inler where id = v_checkin;
  reset role;
  asama := 'gizliyken sahibine gorunen'; gorunen := v_sayi; return next;

  update public.check_inler set moderasyon_gizli = false where id = v_checkin;
  set local role authenticated;
  select count(*) into v_sayi from public.check_inler where id = v_checkin;
  reset role;
  asama := 'gizleme kalkinca sahibine gorunen'; gorunen := v_sayi; return next;
end;
$fn$;

select * from pg_temp.gizleme_olc();

