create or replace function pg_temp.kapi_olc()
returns table(rpc text, sonuc text)
language plpgsql
as $fn$
declare
  v_ad text;
  v_sahte uuid := '00000000-0000-0000-0000-000000000000';
  v_cagrilar text[][] := array[
    ['moderasyon_sikayetleri_listele', 'select public.moderasyon_sikayetleri_listele()'],
    ['moderasyon_sikayet_detayi',      'select public.moderasyon_sikayet_detayi($1)'],
    ['moderasyon_hedef_gecmisi',       'select public.moderasyon_hedef_gecmisi(''kullanici'', $1)'],
    ['moderasyon_sikayeti_karara_bagla','select public.moderasyon_sikayeti_karara_bagla($1, ''incelendi'')'],
    ['moderasyon_kullanici_ara',       'select public.moderasyon_kullanici_ara(''ab'')'],
    ['moderasyon_kullanici_detayi',    'select public.moderasyon_kullanici_detayi($1)'],
    ['moderasyon_konusma_mesajlari',   'select public.moderasyon_konusma_mesajlari($1, ''gerekce'')'],
    ['moderasyon_hesabi_askiya_al',    'select public.moderasyon_hesabi_askiya_al($1, now() + interval ''1 day'', ''sebep'')'],
    ['moderasyon_hesabi_yasakla',      'select public.moderasyon_hesabi_yasakla($1, ''sebep'')'],
    ['moderasyon_hesap_durumunu_kaldir','select public.moderasyon_hesap_durumunu_kaldir($1, ''sebep'')'],
    ['moderasyon_icerigi_gizle',       'select public.moderasyon_icerigi_gizle($1, ''sebep'')'],
    ['moderasyon_gizlemeyi_kaldir',    'select public.moderasyon_gizlemeyi_kaldir($1, ''sebep'')'],
    ['moderasyon_kayitlarini_listele', 'select public.moderasyon_kayitlarini_listele()']
  ];
  i int;
begin
  for i in 1 .. array_length(v_cagrilar, 1) loop
    rpc := v_cagrilar[i][1];
    begin
      execute v_cagrilar[i][2] using v_sahte;
      sonuc := 'GECTI - KAPI ACIK!';
    exception when others then
