    param: { factorType: 'totp', issuer: 'Slooin', friendlyName: 'panel-2' },
  },
]

for (const d of denemeler) {
  const { data, error } = await panel.auth.mfa.enroll(d.param)
  if (error) {
    console.log(`DENEME ${d.ad}: HATA -> ${error.message}`)
  } else {
    console.log(`DENEME ${d.ad}: BASARILI`)
    console.log('   qr var mi   :', !!data.totp?.qr_code)
    console.log('   secret var mi:', !!data.totp?.secret)
    console.log('   uri         :', data.totp?.uri ?? '(yok)')
    // Temizle ki sonraki deneme bozulmasin.
    await panel.auth.mfa.unenroll({ factorId: data.id })
    break
  }
}

