create or replace function pg_temp.bursa_dene()
returns table(sonuc text)
language plpgsql
as $fn$
declare
  v_kullanici uuid;
  v_kayit record;
  v_sayi int := 0;
begin
  select id into v_kullanici from public.profiller limit 1;
  perform set_config('request.jwt.claims',
    json_build_object('sub', v_kullanici, 'role', 'authenticated', 'aal', 'aal1')::text, true);

  for v_kayit in
    select ad, tur, kisi_sayisi
      from public.yakin_mekanlar_yogunluk(40.1826, 29.0665, 5000, null)
     limit 5
  loop
    v_sayi := v_sayi + 1;
    sonuc := v_kayit.ad || '  |  ' || v_kayit.tur || '  |  ' || v_kayit.kisi_sayisi || ' kisi';
    return next;
  end loop;

  if v_sayi = 0 then
    sonuc := 'BOS DONDU';
    return next;
  end if;
exception when others then
  sonuc := 'HATA: ' || sqlerrm;
  return next;
end;
$fn$;

select * from pg_temp.bursa_dene();

